import { createClient } from '@supabase/supabase-js';
import './style.css';

const url = import.meta.env.VITE_SUPABASE_URL || '';
const key = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || '';
const ready = Boolean(url && key);
const db = ready ? createClient(url, key, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } }) : null;
const app = document.querySelector('#app');
const themeKey='remax-unified-theme';
function initThemeToggle(){const root=document.documentElement;let saved='light';try{saved=localStorage.getItem(themeKey)||'light'}catch(e){}const button=document.createElement('button');button.type='button';button.id='themeToggle';button.className='theme-toggle';button.title='Alternar entre modo claro e escuro';function apply(theme){root.dataset.theme=theme;button.textContent=theme==='dark'?'☀ Modo claro':'☾ Modo escuro';button.setAttribute('aria-pressed',String(theme==='dark'));button.setAttribute('aria-label',theme==='dark'?'Ativar modo claro':'Ativar modo escuro');const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==='dark'?'#222326':'#f6f5f1'}button.addEventListener('click',()=>{const next=root.dataset.theme==='dark'?'light':'dark';apply(next);try{localStorage.setItem(themeKey,next)}catch(e){}});apply(saved);document.body.appendChild(button)}
initThemeToggle();

const state = { user: null, homes: [], photos: [], page: 'imoveis', query: '', mode: 'url', draft: null, message: '', offerIds: [], offerForm: null, viewMode: 'list' };
const initials = user => { const meta=user?.user_metadata||{}; const full=String(meta.full_name||meta.name||'').trim(); if(full){const bits=full.split(/\s+/);return (bits.length>1?bits[0][0]+bits[bits.length-1][0]:bits[0].slice(0,2)).toUpperCase()} return String(user?.email||'A').split('@')[0].slice(0,2).toUpperCase(); };
const date = d => d ? new Date(d+'T12:00:00').toLocaleDateString('pt-BR') : '—';
const safe = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeHttpUrl = raw => {try{const u=new URL(String(raw||'').trim());return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const publicListingUrl = id => location.origin + '/imovel/' + encodeURIComponent(String(id || ''));
function videoEmbedUrl(raw){
 try{const u=new URL(String(raw||'').trim());if(!['https:','http:'].includes(u.protocol))return '';const host=u.hostname.toLowerCase().replace(/^www\./,'');
 if(host==='youtu.be'){const id=u.pathname.split('/').filter(Boolean)[0];return id?'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id):''}
 if(['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(host)){const id=u.searchParams.get('v')||u.pathname.match(/\/(?:embed|shorts)\/([^/?]+)/)?.[1];return id?'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id):''}
 if(['vimeo.com','player.vimeo.com'].includes(host)){const id=u.pathname.match(/\/(?:video\/)?(\d+)/)?.[1];return id?'https://player.vimeo.com/video/'+id:''}
 return /\.(mp4|webm|mov)$/i.test(u.pathname)?u.href:'';
 }catch{return ''}
}
const mediaIsVideo = media => media?.kind==='new-video' || /^video(?::|$)/i.test(String(media?.legenda||'')) || Boolean(videoEmbedUrl(media?.url));
function mediaMarkup(media,index=0){
 const src=String(media?.kind||'').startsWith('new')?media.preview:media?.url||'';
 if(mediaIsVideo(media)){const embed=videoEmbedUrl(src);if(embed&&!/\.(mp4|webm|mov)(?:$|\?)/i.test(embed))return '<iframe class="media-video-frame" src="'+safe(embed)+'" title="Vídeo do imóvel '+(index+1)+'" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>';return '<video class="media-video-frame" src="'+safe(src)+'" controls playsinline preload="metadata"></video>'}
 return '<img src="'+safe(src)+'" alt="Mídia '+(index+1)+'">';
}
const say = (s,bad=false) => { let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.append(t)}t.textContent=s;t.classList.toggle('bad',bad);clearTimeout(say.t);say.t=setTimeout(()=>t.remove(),6500); };

