document.querySelector('#new-password').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),password=String(f.get('password')),confirm=String(f.get('confirm')),b=e.target.querySelector('button'),p=document.querySelector('#feedback');if(password!==confirm){p.textContent='As senhas não são iguais.';p.className='error';return}b.disabled=true;b.textContent='Salvando…';const {error}=await db.auth.updateUser({password});if(error){p.textContent=error.message;p.className='error';b.disabled=false;b.textContent='Salvar nova senha →';return}state.user=(await db.auth.getUser()).data.user;await load();};
