 const p=state.homes.find(home=>home.id===id);if(!p)return;
 const media=state.photos.filter(item=>item.imovel_id===id).sort((a,b)=>(a.ordem||0)-(b.ordem||0));
 const images=media.filter(item=>!mediaIsVideo(item));
 const videos=media.filter(item=>mediaIsVideo(item));
 const cover=images.find(item=>item.capa)||images[0];
 const amenities=[...new Set([...(Array.isArray(p.comodidades)?p.comodidades:[]),p.piscina?'Piscina':'',p.churrasqueira?'Churrasqueira':'',p.area_gourmet?'Área gourmet':'',p.servico_praia?'Serviço de praia':''].filter(Boolean))].slice(0,4);
 const popup=window.open('','_blank');
 if(!popup){say('Permita abrir uma nova janela para exportar o PDF.',true);return}
