const moveAmenity=(index,delta)=>{const target=index+delta;if(target<0||target>=amenityOrder.length)return;[amenityOrder[index],amenityOrder[target]]=[amenityOrder[target],amenityOrder[index]];renderAmenities()};
const ordered=()=>photoItems;
