const renderPhotos=()=>{const host=ov.querySelector('#photo-manager-slot');if(host)host.innerHTML=photoHtml();wirePhotos()};
const openPhotoCrop=index=>{
 const photo=photoItems[index];if(!photo||mediaIsVideo(photo))return;
 const initial=photo.crop||readPhotoCrop(photo.url),source=photo.preview||String(photo.url||'').split('#')[0];
 const layer=document.createElement('div');layer.className='crop-backdrop';
 layer.innerHTML='<section class="crop-dialog" role="dialog" aria-modal="true"><div class="crop-dialog-head"><div><b>Ajustar enquadramento</b><small>O recorte será publicado no anúncio. A foto original será preservada.</small></div><button type="button" data-crop-close aria-label="Fechar">×</button></div><div class="crop-preview" data-crop-pan><img alt="Prévia do recorte"></div><p class="crop-pan-hint">☝ Arraste a foto com a mãozinha para reposicionar.</p><label>Zoom <output data-crop-zoom-value></output><input type="range" data-crop-zoom min="1" max="3" step=".05"></label><div class="crop-dialog-actions"><button type="button" class="btn secondary" data-crop-reset>Centralizar posição</button><button type="button" class="btn primary" data-crop-save>Aplicar corte</button></div></section>';
 document.body.append(layer);const preview=layer.querySelector('[data-crop-pan]'),img=layer.querySelector('.crop-preview img');img.src=source;
 const zoom=layer.querySelector('[data-crop-zoom]'),x={value:initial.x},y={value:initial.y};
 const paint=()=>{const z=Number(zoom.value)||1;img.style.objectFit='cover';img.style.objectPosition='center';img.style.transform='translate('+((50-x.value)*(z-1))+'%, '+((50-y.value)*(z-1))+'%) scale('+z+')';layer.querySelector('[data-crop-zoom-value]').textContent=z.toFixed(2)+'×'};
 const set=(v)=>{zoom.value=v.zoom;x.value=v.x;y.value=v.y;paint()};set(initial);
 zoom.oninput=paint;
 let pointer=null,lastX=0,lastY=0;
 preview.onpointerdown=e=>{pointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;preview.setPointerCapture(pointer);preview.classList.add('is-panning');e.preventDefault()};
 preview.onpointermove=e=>{if(pointer!==e.pointerId)return;const rect=preview.getBoundingClientRect(),dx=e.clientX-lastX,dy=e.clientY-lastY;if(Math.abs(dx)>0&&Number(zoom.value)<=1)zoom.value=1.25;x.value=Math.max(0,Math.min(100,x.value-dx/rect.width*100));y.value=Math.max(0,Math.min(100,y.value-dy/rect.height*100));lastX=e.clientX;lastY=e.clientY;paint()};
 const stopPan=e=>{if(pointer!==null&&e.pointerId===pointer){pointer=null;preview.classList.remove('is-panning')}};
 preview.onpointerup=stopPan;preview.onpointercancel=stopPan;
 const close=()=>layer.remove();layer.querySelector('[data-crop-close]').onclick=close;
 layer.onclick=e=>{if(e.target===layer)close()};
 layer.querySelector('[data-crop-reset]').onclick=()=>{x.value=50;y.value=50;paint()};
 layer.querySelector('[data-crop-save]').onclick=()=>{photo.crop={zoom:Number(zoom.value),x:Number(x.value),y:Number(y.value),applied:true};close();renderPhotos()};
};
const wirePhotos=()=>{ov.querySelectorAll('[data-photo-crop]').forEach(btn=>btn.onclick=()=>openPhotoCrop(Number(btn.dataset.photoCrop)));ov.querySelectorAll('[data-photo-up]').forEach(btn=>btn.onclick=()=>movePhoto(Number(btn.dataset.photoUp),-1));ov.querySelectorAll('[data-photo-down]').forEach(btn=>btn.onclick=()=>movePhoto(Number(btn.dataset.photoDown),1));ov.querySelectorAll('[data-photo-remove]').forEach(btn=>btn.onclick=()=>removePhoto(Number(btn.dataset.photoRemove)));let dragging=null;ov.querySelectorAll('[data-photo-drag]').forEach(tile=>{tile.ondragstart=e=>{dragging=Number(tile.dataset.photoDrag);e.dataTransfer.effectAllowed='move';tile.classList.add('dragging')};tile.ondragend=()=>{dragging=null;tile.classList.remove('dragging')};tile.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};tile.ondrop=e=>{e.preventDefault();const target=Number(tile.dataset.photoDrag);if(dragging!==null&&dragging!==target){const moved=photoItems.splice(dragging,1)[0];photoItems.splice(target,0,moved);dragging=null;renderPhotos()}};tile.ontouchstart=()=>{dragging=Number(tile.dataset.photoDrag);tile.classList.add('dragging')};tile.ontouchend=e=>{if(dragging===null)return;const t=e.changedTouches?.[0],targetTile=t?document.elementFromPoint(t.clientX,t.clientY)?.closest('[data-photo-drag]'):null,target=Number(targetTile?.dataset.photoDrag);if(targetTile&&Number.isInteger(target)&&target!==dragging){const moved=photoItems.splice(dragging,1)[0];photoItems.splice(target,0,moved)}dragging=null;renderPhotos()}})};
const movePhoto=(index,delta)=>{const target=index+delta;if(target<0||target>=photoItems.length)return;[photoItems[index],photoItems[target]]=[photoItems[target],photoItems[index]];renderPhotos()};
const removePhoto=index=>{const photo=photoItems[index];if(!photo)return;if(photo.kind==='saved')removedPhotos.push(photo);else if(photo.kind==='new'||photo.kind==='new-video'){URL.revokeObjectURL(photo.preview);newFiles=newFiles.filter(file=>file!==photo.file)}photoItems.splice(index,1);renderPhotos()};
ov.innerHTML=`<section class="modal"><div class="modal-head"><div><small class="kicker">CATÁLOGO</small><h2>${p?'Editar imóvel':'Novo imóvel'}</h2></div><button data-close aria-label="Fechar">×</button></div><form id="home-form" class="form"><div><label>Nome do anúncio</label><input name="titulo" value="${safe(p?.titulo||'')}" required placeholder="Casa Azul — Juquehy"></div><div><label>Apelido privado <small>(somente na área interna)</small></label><input name="apelido_privado" value="${safe(p?.apelido_privado||'')}" placeholder="Casa da esquina"><small class="field-help">Nunca será exibido no anúncio, link público, compartilhamento ou PDF.</small></div><div><label>Link do anúncio original</label><input name="url_origem" type="url" inputmode="url" value="${safe(p?.url_origem||'')}" placeholder="https://..."><small class="field-help">Link da publicação original do imóvel.</small></div><div class="row"><div><label>Bairro</label><input name="bairro" value="${safe(p?.bairro||'')}"></div><div><label>Capacidade de hóspedes</label><input name="capacidade" type="number" min="1" value="${p?.capacidade||''}" required></div></div><div class="row"><div><label>Dormitórios</label><input name="dormitorios" type="number" min="0" value="${p?.dormitorios??''}" required></div><div><label>Suítes</label><input name="suites" type="number" min="0" value="${p?.suites??0}"></div></div><div><label>Distância da praia (m)</label><input name="distancia_praia" type="number" min="0" value="${p?.distancia_praia??''}"></div><label>Disponibilidade</label><select name="disponibilidade_status"><option value="a_confirmar" ${!p||p.disponibilidade_status==='a_confirmar'?'selected':''}>A confirmar</option><option value="disponivel" ${p?.disponibilidade_status==='disponivel'?'selected':''}>Disponível</option><option value="reservado" ${p?.disponibilidade_status==='reservado'?'selected':''}>Reservado</option><option value="indisponivel" ${p?.disponibilidade_status==='indisponivel'?'selected':''}>Indisponível</option></select><div class="amenity-editor"><label>Comodidades que valorizam o imóvel</label><div class="amenity-checks">${amenityOptions.map(name=>'<label><input type="checkbox" data-amenity="'+safe(name)+'" '+(amenityOrder.includes(name)?'checked':'')+'> '+safe(name)+'</label>').join('')}<label><input type="checkbox" name="ativo" ${p?.ativo!==false?'checked':''}> Ativo</label></div><p>Você pode mudar a ordem abaixo. Só as quatro primeiras aparecem no PDF.</p><div id="amenity-order-slot">${amenityOrderHtml()}</div></div><label>Descrição e comodidades</label><textarea name="descricao" rows="3">${safe(p?.descricao||'')}</textarea><div id="photo-manager-slot">${photoHtml()}</div><label class="upload-zone" for="home-photos"><span class="upload-icon">＋</span><b>Adicionar fotos</b><small>Toque para escolher uma ou várias imagens</small><small>JPG, PNG ou WebP · até 25 MB por foto</small></label><input id="home-photos" name="fotos" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><button type="button" id="add-video-link" class="btn secondary full">Adicionar link de vídeo</button><label class="upload-zone video-upload-zone" for="home-videos"><span class="upload-icon">▶</span><b>Enviar arquivo de vídeo</b><small>MP4, WebM ou MOV · sem limite específico no BancoImob</small></label><input id="home-videos" type="file" accept="video/mp4,video/webm,video/quicktime" multiple hidden><div class="actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary" type="submit">${p?'Salvar alterações':'Cadastrar imóvel'}</button></div></form></section>`;
document.body.append(ov);ov.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>{newFiles.forEach(file=>URL.revokeObjectURL(file.preview));ov.remove()});wirePhotos();ov.querySelectorAll('[data-amenity]').forEach(input=>input.onchange=()=>{const name=input.dataset.amenity;if(input.checked&&!amenityOrder.includes(name))amenityOrder.push(name);else if(!input.checked)amenityOrder=amenityOrder.filter(x=>x!==name);renderAmenities()});renderAmenities();
ov.querySelector('#add-video-link').onclick=()=>{const raw=prompt('Cole o link público do vídeo (YouTube, Vimeo ou arquivo MP4/WebM/MOV).');if(!raw)return;const videoUrl=raw.trim();if(!videoEmbedUrl(videoUrl)){say('Use um link público do YouTube, Vimeo ou arquivo MP4/WebM/MOV.',true);return}photoItems.push({kind:'video',url:videoUrl,legenda:'VIDEO'});renderPhotos()};
